import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({
    strict: false,
    validateFormats: false,
    coerceTypes: false,
    useDefaults: false,
  } as ConstructorParameters<typeof Ajv>[0]);
  private readonly resolvedValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compileValidator(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private compileValidator(definition: ToolDefinition): ValidateFunction {
    try {
      return this.validator.compile(definition.inputSchema);
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      throw new Error(`Unable to compile input schema for tool ${definition.name}: ${detail}`, {cause: error});
    }
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) return tool.validator;

    const cached = this.resolvedValidators.get(definition.inputSchema);
    if (cached) return cached;

    const validator = this.compileValidator(definition);
    this.resolvedValidators.set(definition.inputSchema, validator);
    return validator;
  }

  private validateInput(validate: ValidateFunction, input: Record<string, unknown>): ToolResponse | undefined {
    if (validate(input)) return undefined;

    const error = validate.errors?.[0];
    if (error?.keyword === 'required' && 'missingProperty' in error.params) {
      return {result: `Tool input validation failed: ${String(error.params.missingProperty)} is required.`};
    }
    if (error?.keyword === 'type' && 'type' in error.params) {
      const path = 'instancePath' in error && error.instancePath ? String(error.instancePath) : '(input)';
      return {result: `Tool input validation failed: ${path} must be ${String(error.params.type)}.`};
    }
    if (error?.keyword === 'enum' && 'allowedValues' in error.params) {
      const path = 'instancePath' in error && error.instancePath ? String(error.instancePath) : '(input)';
      return {
        result: `Tool input validation failed: ${path} must be one of ${JSON.stringify(error.params.allowedValues)}.`,
      };
    }
    return {result: 'Tool input validation failed.'};
  }

  /** Validates tool input; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const rejection = this.validateInput(this.validatorFor(tool, definition), input);
    if (rejection) return rejection;
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry.execute', () => {
  it('returns a ToolResponse naming the missing required field and does not invoke the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/location.*required|required.*location/i),
    });
  });

  it('throws at register time when the inputSchema is uncompilable and the message names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {forecast: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('rejects an enum value with its field path and allowed values', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_temperature',
        description: 'Get a temperature in a supported unit',
        inputSchema: {
          type: 'object',
          properties: {unit: {enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('get_temperature', {unit: 'kelvin'});

    expect(response.result).toMatch(/unit.*celsius.*fahrenheit/i);
  });
});
